```cypher
MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(:Category {name: 'Bikes'})
WHERE EXISTS {
  MATCH (p)<-[:HAS_LINE]-(so:SalesOrder)-[:IN_TERRITORY]->(:Territory {name: 'Northwest'})
  WHERE date_part('year', so.order_date) = 2024
}
AND NOT EXISTS {
  MATCH (p)<-[:HAS_LINE]-(so:SalesOrder)-[:IN_TERRITORY]->(:Territory {name: 'Central'})
  WHERE date_part('year', so.order_date) = 2024
}
RETURN p.product_number AS product_number
ORDER BY p.product_number
```

